-- public.milk_go(p_world uuid, p_uid uuid, c creature)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.milk_go(p_world uuid, p_uid uuid, c creature)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare v_litres int := milk_litres(c.species); v_ql double precision; v_part item; v_now int;
        v_made double precision; v_more boolean := false; v_id bigint;
begin
  -- What it has been fed on is what comes out of it.
  v_ql := greatest(1, least(100, 20 + c.fleece * 40 + c.hunger * 30));
  if v_litres >= bucket_litres() then
    if not consume(p_world, p_uid, 'bucket', 1) then return; end if;
    perform give(p_world, p_uid, 'milk_bucket', 1, v_ql);
    -- A Farmer's Milkmaid fills a second bucket now and then, if there is one.
    if random() < pk(p_world, p_uid, 'more:milk_creature', 0) then
      v_more := consume(p_world, p_uid, 'bucket', 1);
      if v_more then perform give(p_world, p_uid, 'milk_bucket', 1, v_ql); end if;
    end if;
    v_now := v_litres;
    v_made := v_ql;
  else
    -- A Gorral: its litres into the part bucket it started, or into an empty one.
    select i.* into v_part from item i
     where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid and i.def = 'milk_part' and not i.locked
     order by i.id limit 1 for update;
    if v_part.id is not null then
      v_now := least(bucket_litres()::int, coalesce(v_part.charges, 0)::int + v_litres);
      v_made := milk_part_ql(coalesce(v_part.charges, 0), v_part.ql, v_litres, v_ql);
      if v_now >= bucket_litres() then
        perform vessel_becomes(v_part.id, 'milk_bucket');
        -- The one that changed: the row itself, or the newest off the top of its pile.
        select i.id into v_id from item i
         where i.world_id = p_world and i.holder = v_part.holder and i.holder_uid is not distinct from v_part.holder_uid
           and i.def = 'milk_bucket' and (i.id = v_part.id or i.id > v_part.id)
         order by (i.id = v_part.id) desc, i.id desc limit 1;
        update item set ql = v_made where id = v_id;
      else
        update item set charges = v_now, ql = v_made where id = v_part.id;
      end if;
    else
      if not consume(p_world, p_uid, 'bucket', 1) then return; end if;
      v_now := v_litres;
      v_made := v_ql;
      v_id := give(p_world, p_uid, 'milk_part', 1, v_made);
      update item set charges = v_now where id = v_id;
    end if;
  end if;
  update creature set fleece = 0 where world_id = p_world and id = c.id;
  perform beast_learns(p_world, c.id, 'tended');
  perform skill_told(p_world, p_uid, 'farming', 0.3);
  perform journal_note(p_world, p_uid, 'milked:' || c.species);
  perform wtell(p_world, p_uid, milked_says(c.name, v_now, v_made, v_more), 'event');
end $function$
